"""Windows overlapped byte pipes. No filesystem, socket or database operations.

Endpoints are single-thread-owned. poll performs bounded nonblocking work;
close cancels and drains outstanding operations before releasing their buffers.
"""
import ctypes
import os
from collections import deque
from ctypes import wintypes as W



class PipeDisconnected(OSError):
    pass


class QueueFull(BufferError):
    pass


class OVERLAPPED(ctypes.Structure):
    _fields_ = [("Internal", ctypes.c_size_t), ("InternalHigh", ctypes.c_size_t),
                ("Offset", W.DWORD), ("OffsetHigh", W.DWORD), ("hEvent", W.HANDLE)]


class SECURITY_ATTRIBUTES(ctypes.Structure):
    _fields_ = [("nLength", W.DWORD), ("lpSecurityDescriptor", W.LPVOID),
                ("bInheritHandle", W.BOOL)]


if os.name == "nt":
    _k = ctypes.WinDLL("kernel32", use_last_error=True)
    _a = ctypes.WinDLL("advapi32", use_last_error=True)

    def _bind(dll, name, result, args):
        fn = getattr(dll, name)
        fn.restype, fn.argtypes = result, args
        return fn

    _create = _bind(_k, "CreateNamedPipeW", W.HANDLE,
                    [W.LPCWSTR, W.DWORD, W.DWORD, W.DWORD, W.DWORD, W.DWORD,
                     W.DWORD, ctypes.POINTER(SECURITY_ATTRIBUTES)])
    _open = _bind(_k, "CreateFileW", W.HANDLE,
                  [W.LPCWSTR, W.DWORD, W.DWORD, W.LPVOID, W.DWORD, W.DWORD, W.HANDLE])
    _event = _bind(_k, "CreateEventW", W.HANDLE, [W.LPVOID, W.BOOL, W.BOOL, W.LPCWSTR])
    _close = _bind(_k, "CloseHandle", W.BOOL, [W.HANDLE])
    _reset = _bind(_k, "ResetEvent", W.BOOL, [W.HANDLE])
    _connect = _bind(_k, "ConnectNamedPipe", W.BOOL, [W.HANDLE, ctypes.POINTER(OVERLAPPED)])
    _read = _bind(_k, "ReadFile", W.BOOL,
                  [W.HANDLE, W.LPVOID, W.DWORD, ctypes.POINTER(W.DWORD), ctypes.POINTER(OVERLAPPED)])
    _write = _bind(_k, "WriteFile", W.BOOL,
                   [W.HANDLE, W.LPVOID, W.DWORD, ctypes.POINTER(W.DWORD), ctypes.POINTER(OVERLAPPED)])
    _result = _bind(_k, "GetOverlappedResult", W.BOOL,
                    [W.HANDLE, ctypes.POINTER(OVERLAPPED), ctypes.POINTER(W.DWORD), W.BOOL])
    _cancel = _bind(_k, "CancelIoEx", W.BOOL, [W.HANDLE, ctypes.POINTER(OVERLAPPED)])
    _process = _bind(_k, "GetCurrentProcess", W.HANDLE, [])
    _token = _bind(_a, "OpenProcessToken", W.BOOL, [W.HANDLE, W.DWORD, ctypes.POINTER(W.HANDLE)])
    _token_info = _bind(_a, "GetTokenInformation", W.BOOL,
                        [W.HANDLE, ctypes.c_int, W.LPVOID, W.DWORD, ctypes.POINTER(W.DWORD)])
    _sid_string = _bind(_a, "ConvertSidToStringSidW", W.BOOL,
                        [W.LPVOID, ctypes.POINTER(W.LPWSTR)])
    _descriptor = _bind(_a, "ConvertStringSecurityDescriptorToSecurityDescriptorW", W.BOOL,
                        [W.LPCWSTR, W.DWORD, ctypes.POINTER(W.LPVOID), ctypes.POINTER(W.DWORD)])
    _free = _bind(_k, "LocalFree", W.LPVOID, [W.LPVOID])


def _error():
    return ctypes.WinError(ctypes.get_last_error())


def _security():
    """Explicit protected DACL granting only the process user's SID access."""
    token = W.HANDLE()
    sid = W.LPWSTR()
    if not _token(_process(), 8, ctypes.byref(token)):
        raise _error()
    try:
        size = W.DWORD()
        _token_info(token, 1, None, 0, ctypes.byref(size))
        info = ctypes.create_string_buffer(size.value)
        if not _token_info(token, 1, info, size, ctypes.byref(size)):
            raise _error()
        sid_ptr = ctypes.cast(info, ctypes.POINTER(W.LPVOID))[0]
        if not _sid_string(sid_ptr, ctypes.byref(sid)):
            raise _error()
        descriptor = W.LPVOID()
        if not _descriptor("D:P(A;;GA;;;" + sid.value + ")", 1,
                           ctypes.byref(descriptor), None):
            raise _error()
        return SECURITY_ATTRIBUTES(ctypes.sizeof(SECURITY_ATTRIBUTES), descriptor, False)
    finally:
        if sid:
            _free(ctypes.cast(sid, W.LPVOID))
        _close(token)


class _Operation:
    def __init__(self):
        self.ov = OVERLAPPED()
        self.ov.hEvent = _event(None, True, False, None)
        if not self.ov.hEvent:
            raise _error()
        self.pending = False
        self.buffer = None


class PipeEndpoint:
    def __init__(self, name, server=False, max_frame_bytes=MAX_FRAME_BYTES,
                 max_queue_bytes=128 * 1024 * 1024):
        if os.name != "nt":
            raise OSError("named pipes require Windows")
        prefix = "\\\\.\\pipe\\"
        if name.startswith(prefix):
            name = name[len(prefix):]
        if not name or any(c in name for c in "\\/\x00"):
            raise ValueError("pipe name must be a local simple name")
        self.name = prefix + name
        self.server = server
        self.connected = False
        self.closed = False
        self.handle = None
        self.framer = Framer(max_frame_bytes)
        self.max_frame_bytes = max_frame_bytes
        self.max_queue_bytes = max_queue_bytes
        self.queue = deque()
        self.queued_bytes = 0
        self.offset = 0
        self.ops = []
        try:
            for _ in range(3):
                self.ops.append(_Operation())
            self.connect_op, self.read_op, self.write_op = self.ops
            if server:
                sa = _security()
                try:
                    # duplex | overlapped | first instance; byte mode | reject remote.
                    handle = _create(self.name, 3 | 0x40000000 | 0x00080000,
                                     8, 1, 65536, 65536, 0, ctypes.byref(sa))
                finally:
                    _free(sa.lpSecurityDescriptor)
                if handle == ctypes.c_void_p(-1).value:
                    raise _error()
                self.handle = handle
        except Exception:
            self.close()
            raise

    def send(self, message):
        if self.closed:
            raise PipeDisconnected("endpoint is closed")
        frame = encode_frame(message, self.max_frame_bytes)
        if self.queued_bytes + len(frame) > self.max_queue_bytes:
            raise QueueFull("outbound pipe queue is full")
        self.queue.append(frame)
        self.queued_bytes += len(frame)

    def _complete(self, op):
        count = W.DWORD()
        if not _result(self.handle, ctypes.byref(op.ov), ctypes.byref(count), False):
            error = ctypes.get_last_error()
            if error == 996:  # ERROR_IO_INCOMPLETE
                return None
            raise PipeDisconnected(error, "pipe operation failed")
        op.pending = False
        return count.value

    def _connection(self):
        if self.connected:
            return True
        if not self.server:
            handle = _open(self.name, 0xC0000000, 0, None, 3, 0x40000000, None)
            if handle == ctypes.c_void_p(-1).value:
                error = ctypes.get_last_error()
                if error in (2, 231):  # absent or busy: retry next poll
                    return False
                raise OSError(error, "cannot connect to local pipe")
            self.handle = handle
            self.connected = True
            return True
        op = self.connect_op
        if op.pending:
            if self._complete(op) is None:
                return False
        elif not _connect(self.handle, ctypes.byref(op.ov)):
            error = ctypes.get_last_error()
            if error == 997:
                op.pending = True
                return False
            if error != 535:  # ERROR_PIPE_CONNECTED: client won the race
                raise PipeDisconnected(error, "pipe connect failed")
        self.connected = True
        return True

    def _io(self, op, writing):
        if op.pending:
            count = self._complete(op)
            if count is None:
                return None
        else:
            if writing and not self.queue:
                return None
            _reset(op.ov.hEvent)
            if writing:
                data = self.queue[0][self.offset:self.offset + 65536]
                op.buffer = ctypes.create_string_buffer(data, len(data))
            else:
                op.buffer = ctypes.create_string_buffer(65536)
            count_out = W.DWORD()
            fn = _write if writing else _read
            if not fn(self.handle, op.buffer, len(op.buffer), ctypes.byref(count_out),
                      ctypes.byref(op.ov)):
                error = ctypes.get_last_error()
                if error == 997:
                    op.pending = True
                    return None
                raise PipeDisconnected(error, "pipe I/O failed")
            count = count_out.value
        if not count:
            raise PipeDisconnected("pipe peer disconnected")
        if writing:
            self.offset += count
            if self.offset == len(self.queue[0]):
                self.queued_bytes -= len(self.queue.popleft())
                self.offset = 0
            op.buffer = None
            return []
        data = op.buffer.raw[:count]
        op.buffer = None
        return self.framer.feed(data)

    def poll(self):
        if self.closed:
            raise PipeDisconnected("endpoint is closed")
        messages = []
        try:
            if not self._connection():
                return []
            for _ in range(16):
                read = self._io(self.read_op, False)
                if read is not None:
                    messages.extend(read)
                written = self._io(self.write_op, True)
                if read is None and written is None:
                    break
            return messages
        except Exception:
            self.close()
            if messages:
                # Deliver already received frames; next poll reports the closure.
                return messages
            raise

    def close(self):
        if self.closed:
            return
        self.closed = True
        self.connected = False
        if self.handle is not None:
            for op in self.ops:
                if op.pending:
                    _cancel(self.handle, ctypes.byref(op.ov))
            for op in self.ops:
                if op.pending:
                    count = W.DWORD()
                    # Drain cancellation before releasing OVERLAPPED/buffer memory.
                    _result(self.handle, ctypes.byref(op.ov), ctypes.byref(count), True)
                    op.pending = False
            _close(self.handle)
            self.handle = None
        for op in self.ops:
            _close(op.ov.hEvent)
            op.buffer = None
        self.ops = []
        self.queue.clear()
        self.queued_bytes = 0

# ---- service/ipc_bridge/qmt_runtime/executor.py ----
"""QMT-only in-memory IPC executor; no persistence or worker threads."""
import collections
import json
import time
import math
import uuid
import threading



def console_log(level, message, **fields):
    """Bounded metadata only; never serialize request/response or native objects."""
    allowed = ('request_id', 'method', 'elapsed_ms', 'code', 'qmt_method', 'qmt_call_id',
               'return_type', 'return_count', 'error_code', 'error_type', 'stage',
               'attempt_id', 'order_id', 'client_order_id')
    try:
        record = {'level': str(level)[:16], 'message': str(message)[:128]}
        for key in allowed:
            value = fields.get(key)
            if type(value) is str:
                record[key] = value[:256]
            elif type(value) in (int, bool):
                record[key] = value
            elif type(value) is float and math.isfinite(value):
                record[key] = round(value, 3)
        print(json.dumps(record, ensure_ascii=True, allow_nan=False))
    except Exception:
        pass


class DeferredResult(object):
    def __init__(self, step):
        self.step = step


class QmtRuntime(object):
    def __init__(self, role, bridge_id, account_id, pipe_name, execute,
                 endpoint_factory=PipeEndpoint, clock=time.monotonic,
                 event_limit=4096, request_limit=100000, budget_ms=50):
        self.role, self.bridge_id, self.account_id = role, bridge_id, account_id
        self.pipe_name, self.execute = pipe_name, execute
        self.endpoint_factory, self.clock = endpoint_factory, clock
        self.event_limit, self.request_limit = event_limit, request_limit
        self.budget = budget_ms / 1000.0
        self.boot_id = str(uuid.uuid4())
        self.endpoint = None
        self.session_id = None
        self.hello_sent = False
        self.closed = False
        self.gap = False
        self.seq = 0
        self.events = collections.deque()
        self.sent_seq = 0
        self.seen = set()
        self.pending_ids = set()
        self.request_context = {}
        self.inbox = collections.deque()
        self.jobs = collections.deque()
        self.authority = None
        self.authority_until = 0
        self.challenge_id = None
        self.challenge_until = 0
        self.challenge_started = 0
        self.next_challenge = 0
        self.next_heartbeat = 0
        self.guard = threading.Lock()
        self.tick_guard = threading.Lock()
        self.capabilities = {'protocol': 1, 'callbacks': role == 'order'}

    def _send(self, value):
        value.setdefault('boot_id', self.boot_id)
        value.setdefault('session_id', self.session_id)
        self.endpoint.send(value)

    def disconnect(self):
        if self.endpoint is not None:
            self.endpoint.close()
        self.endpoint = None
        self.session_id = None
        self.hello_sent = False
        self.authority = None
        self.authority_until = 0
        self.challenge_id = None
        self.inbox.clear()
        self.jobs.clear()
        self.pending_ids.clear()
        self.sent_seq = 0
        self.next_heartbeat = self.next_challenge = 0

    def close(self):
        self.closed = True
        if self.tick_guard.acquire(False):
            try:
                self.disconnect()
            finally:
                self.tick_guard.release()
        # An active tick owns native OVERLAPPED memory until its finally block.

    def observe(self, event, payload):
        with self.guard:
            self.seq += 1
            if len(self.events) >= self.event_limit:
                self.gap = True
                return
            self.events.append({'type': 'event', 'seq': self.seq,
                                'event': event, 'payload': payload})

    def _request(self, frame):
        request_id = frame.get('request_id')
        if not isinstance(request_id, str) or not request_id:
            return
        result = {'type': 'result', 'request_id': request_id}
        started = self.clock()
        method = frame.get('method')
        console_log('INFO', 'IPC request started', request_id=request_id, method=method, elapsed_ms=0)
        try:
            if request_id in self.pending_ids:
                raise RuntimeError('DUPLICATE_REQUEST')
            if method in ('order.submit', 'order.prepare_step', 'order.cancel_action'):
                if request_id in self.seen:
                    raise RuntimeError('DUPLICATE_REQUEST')
                if len(self.seen) >= self.request_limit:
                    raise RuntimeError('REQUEST_CAPACITY_EXHAUSTED')
                self.seen.add(request_id)
            if not isinstance(frame.get('expires_at'), (int, float)) or time.time() >= frame['expires_at']:
                raise RuntimeError('REQUEST_EXPIRED')
            method, params = frame.get('method'), frame.get('params', {})
            if not isinstance(method, str) or not isinstance(params, dict):
                raise RuntimeError('INVALID_REQUEST')
            if method in ('order.submit', 'order.prepare_step', 'order.cancel_action'):
                if (self.gap or self.authority is None or
                        self.clock() >= self.authority_until or
                        frame.get('authority') != self.authority):
                    raise RuntimeError('AUTHORITY_UNAVAILABLE')
            if self.closed:
                raise RuntimeError('STRATEGY_STOPPED')
            self.request_context = {'request_id': request_id, 'method': method}
            payload = self.execute(method, params)
            if isinstance(payload, DeferredResult):
                if len(self.jobs) >= 128:
                    raise RuntimeError('BATCH_CAPACITY_EXHAUSTED')
                self.pending_ids.add(request_id)
                self.jobs.append((result, payload, frame['expires_at'], method, started))
                return
            result.update(status=200, payload=payload)
        except Exception as exc:
            code = getattr(exc, 'code', str(exc) if isinstance(exc, RuntimeError) else 'QMT_ERROR')
            result.update(status=getattr(exc, 'status', 503), code=code,
                          message=str(exc))
        self._log_result(result, method, started)
        self._send(result)

    def _log_result(self, result, method, started):
        failed = result.get('status', 500) >= 400
        console_log('ERROR' if failed else 'INFO',
                    'IPC request failed' if failed else 'IPC request finished',
                    request_id=result['request_id'], method=method, code=result.get('code'),
                    elapsed_ms=(self.clock() - started) * 1000)

    def _step_job(self):
        if self.closed or not self.jobs:
            return
        result, job, deadline, method, started = self.jobs.popleft()
        try:
            if time.time() >= deadline:
                raise RuntimeError('REQUEST_EXPIRED')
            done, payload = job.step()
            if not done:
                self.jobs.append((result, job, deadline, method, started))
                return
            result.update(status=200, payload=payload)
        except Exception as exc:
            result.update(status=getattr(exc, 'status', 503),
                          code=getattr(exc, 'code', 'QMT_ERROR'), message=str(exc))
        self.pending_ids.discard(result['request_id'])
        self._log_result(result, method, started)
        self._send(result)

    def _frame(self, frame):
        kind = frame.get('type')
        if kind == 'welcome':
            if (frame.get('protocol') != 1 or frame.get('role') != self.role or
                    frame.get('bridge_id') != self.bridge_id or
                    frame.get('account_id') != self.account_id or
                    not isinstance(frame.get('session_id'), str)):
                raise RuntimeError('INVALID_WELCOME')
            if self.session_id is not None:
                raise RuntimeError('DUPLICATE_WELCOME')
            self.session_id = frame['session_id']
            return
        if not self.session_id or frame.get('session_id') != self.session_id:
            return
        if kind == 'authority_grant':
            grant = frame.get('authority')
            remaining = frame.get('remaining_seconds')
            if (self.challenge_id is not None and
                    frame.get('challenge_id') == self.challenge_id and
                    self.clock() < self.challenge_until and
                    isinstance(grant, list) and len(grant) == 2 and
                    isinstance(remaining, (int, float)) and not isinstance(remaining, bool) and
                    math.isfinite(remaining) and remaining > 0):
                deadline = min(self.challenge_until, self.challenge_started + min(remaining, 0.5))
                if self.clock() >= deadline:
                    return
                self.authority, self.authority_until = grant, deadline
                self.challenge_id = None
        elif kind == 'ack' and frame.get('boot_id') == self.boot_id:
            seq = frame.get('seq')
            if isinstance(seq, int) and not isinstance(seq, bool) and seq <= self.sent_seq:
                with self.guard:
                    while self.events and self.events[0]['seq'] <= seq:
                        self.events.popleft()
        elif kind == 'request':
            self._request(frame)

    def tick(self):
        if self.closed or not self.tick_guard.acquire(False):
            return
        try:
            if not self.closed:
                self._tick()
        except Exception as exc:
            print('IPC disconnected: {0}: {1}'.format(type(exc).__name__, exc))
            self.disconnect()
        finally:
            try:
                if self.closed:
                    self.disconnect()
            finally:
                self.tick_guard.release()

    def _tick(self):
        started = self.clock()
        if self.endpoint is None:
            self.endpoint = self.endpoint_factory(self.pipe_name, server=False)
        frames = self.endpoint.poll()
        if self.closed or not self.endpoint.connected:
            return
        if not self.hello_sent:
            self._send({'type': 'hello', 'protocol': 1, 'role': self.role,
                        'bridge_id': self.bridge_id, 'account_id': self.account_id,
                        'capabilities': self.capabilities})
            self.hello_sent = True
        if len(self.inbox) + len(frames) > 4096:
            raise RuntimeError('INBOX_OVERFLOW')
        self.inbox.extend(frames)
        while not self.closed and self.inbox and self.clock() - started < self.budget:
            self._frame(self.inbox.popleft())
        if self.closed or not self.session_id:
            return
        if self.clock() - started < self.budget:
            self._step_job()
        now = self.clock()
        if self.role == 'order' and now >= self.next_challenge:
            self.challenge_id = str(uuid.uuid4())
            self.challenge_started = now
            self.challenge_until = now + 0.5
            self.next_challenge = now + 0.15
            self._send({'type': 'authority_challenge', 'challenge_id': self.challenge_id})
        if now >= self.next_heartbeat:
            self._send({'type': 'heartbeat', 'ready': True, 'authority_ready': self.authority is not None and now < self.authority_until and not self.gap, 'qmt_ms': (self.clock() - started) * 1000,
                        'gap': self.gap, 'capabilities': self.capabilities})
            if self.gap:
                self._send({'type': 'event_gap', 'seq': self.seq})
            self.next_heartbeat = now + 0.25
        with self.guard:
            pending = []
            for event in self.events:
                if event['seq'] > self.sent_seq:
                    pending.append(dict(event))
                    if len(pending) == 64:
                        break
        for event in pending:
            if self.clock() - started >= self.budget:
                break
            self._send(event)
            self.sent_seq = event['seq']

